-- ATUALIZAÇÃO COMPLETA DO BANCO — 09/10/2026
-- Rode tudo de uma vez no SQL Editor do Supabase (pode rodar mais de uma vez sem problema).
-- Parte 1: numeração dos contratos a partir do 91 (0027)
-- Parte 2: memorial descritivo do Porto Franco — 814 lotes (0028)

-- 0027 — Numeração própria dos contratos (pedido de 09/10).
-- O 1º contrato emitido pelo sistema recebe o nº 91 (os até 90 já existem
-- fora do sistema), o seguinte 92, e assim por diante. O número é dado na
-- 1ª emissão e fica gravado na proposta: emitir de novo (nova versão) mantém
-- o mesmo número. Proposta que nunca vira contrato não gasta número.

create sequence if not exists contrato_numero_seq start with 91 minvalue 1;

alter table propostas add column if not exists numero_contrato integer unique;

create or replace function atribuir_numero_contrato(p_proposta uuid)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  n integer;
begin
  select numero_contrato into n from propostas where id = p_proposta for update;
  if not found then
    raise exception 'proposta % não encontrada', p_proposta;
  end if;
  if n is null then
    n := nextval('contrato_numero_seq');
    update propostas set numero_contrato = n where id = p_proposta;
  end if;
  return n;
end;
$$;

revoke all on function atribuir_numero_contrato(uuid) from public, anon, authenticated;
grant execute on function atribuir_numero_contrato(uuid) to service_role;


-- 0028 — Memorial descritivo do Porto Franco nos contratos (pedido de 09/10).
-- Fonte: MEMORIAL DESCRITIVO CONDOMÍNIO PORTO FRANCO R3 (Mary Macêdo, CAU
-- A170351-0, Mossoró, 06/10/2025) -- 814 lotes, 36 quadras. Texto copiado
-- exatamente como está no memorial (inclusive os erros de digitação dele).
-- O contrato do Porto Franco usa esta tabela no item V (área + frente,
-- fundo e laterais). Também acerta lotes.tamanho_m2 = área privativa.

create table if not exists lotes_memorial (
  condominio_slug text not null,
  quadra text not null,               -- sem zero à esquerda: '1', '2', ... '36'
  lote_numero int not null,
  area_privativa numeric(10,2) not null,
  area_comum numeric(10,2) not null,
  area_real numeric(10,2) not null,
  area_texto text not null,           -- linha "Área privativa: ... Área real: ..." do memorial
  confrontacoes text[] not null,      -- frente, fundo, lado direito, lado esquerdo
  fonte text not null default 'Memorial descritivo R3 - 06/10/2025',
  atualizado_em timestamptz not null default now(),
  primary key (condominio_slug, quadra, lote_numero)
);
-- Só o backend (service role) lê/escreve.
alter table lotes_memorial enable row level security;
revoke all on lotes_memorial from anon, authenticated;

on conflict (condominio_slug, quadra, lote_numero) do update set
  area_privativa = excluded.area_privativa,
  area_comum = excluded.area_comum,
  area_real = excluded.area_real,
  area_texto = excluded.area_texto,
  confrontacoes = excluded.confrontacoes,
  fonte = excluded.fonte,
  atualizado_em = now();

-- Área do lote no sistema = área privativa do memorial (guarda o valor antigo
-- pra conferência no resultado final).
drop table if exists _pf_area_alterada;
create temp table _pf_area_alterada as
select l.id, l.quadra, l.lote_numero, l.tamanho_m2 as area_antiga, m.area_privativa as area_nova
from lotes l
join condominios c on c.id = l.condominio_id
join lotes_memorial m
  on m.condominio_slug = 'porto-franco'
 and m.quadra = coalesce(nullif(ltrim(l.quadra, '0'), ''), '0')
 and m.lote_numero = l.lote_numero
where c.slug = 'porto-franco'
  and l.tamanho_m2 is distinct from m.area_privativa;

update lotes l set tamanho_m2 = a.area_nova, updated_at = now()
from _pf_area_alterada a where l.id = a.id;

-- Conferência (uma linha): quantos lotes do sistema casaram com o memorial,
-- quais ficaram de fora e quais tiveram a área corrigida.
select
  (select last_value from contrato_numero_seq) as proximo_numero_contrato,
  (select count(*) from lotes_memorial where condominio_slug = 'porto-franco') as lotes_no_memorial,
  (select count(*) from lotes l join condominios c on c.id = l.condominio_id where c.slug = 'porto-franco') as lotes_no_sistema,
  (select count(*) from lotes l join condominios c on c.id = l.condominio_id
     join lotes_memorial m on m.condominio_slug = 'porto-franco'
      and m.quadra = coalesce(nullif(ltrim(l.quadra, '0'), ''), '0') and m.lote_numero = l.lote_numero
   where c.slug = 'porto-franco') as lotes_com_memorial,
  (select string_agg('Q' || l.quadra || '-L' || l.lote_numero, ', ' order by l.quadra, l.lote_numero)
     from lotes l join condominios c on c.id = l.condominio_id
    where c.slug = 'porto-franco'
      and not exists (select 1 from lotes_memorial m where m.condominio_slug = 'porto-franco'
                        and m.quadra = coalesce(nullif(ltrim(l.quadra, '0'), ''), '0') and m.lote_numero = l.lote_numero)
  ) as lotes_sem_memorial,
  (select string_agg('Q' || quadra || '-L' || lote_numero || ': ' || area_antiga || ' -> ' || area_nova, '; ' order by quadra, lote_numero)
     from _pf_area_alterada) as areas_corrigidas;
